func newProbeRepo(t *testing.T) (*runcontrol.SQLiteRepository, runcontrol.Owner) {
	t.Helper()
	ctx := context.Background()
	repository, err := runcontrol.OpenSQLite(ctx, t.TempDir(), runcontrol.SQLiteOptions{})
	if err != nil {
