	return repository, owner
}

// Probe 1: does a terminal prior run with the same TUI-style digest block a fresh accept?
func TestProbeAliasBlocksRerunAfterTerminal(t *testing.T) {
	repository, owner := newProbeRepo(t)
	manager := newDurableOperationManager(repository, owner)
	req := OperationRequest{Kind: OperationSmokeStart, Project: "alpha", Sprint: "1"}
	digest := "deadbeef"
	first, err := manager.AcceptOperation(context.Background(), Confirmation{Request: req}, digest)
	if err != nil {
		t.Fatalf("first accept: %v", err)
	}
	if err := manager.FinishOperation(context.Background(), first.RunID, OperationFailed, errors.New("smoke failed")); err != nil {
		t.Fatalf("finish: %v", err)
	}
	second, err := manager.AcceptOperation(context.Background(), Confirmation{Request: req}, digest)
	if err != nil {
		t.Fatalf("second accept errored: %v", err)
	}
	t.Logf("PROBE1 second.Existing=%v second.RunID=%q second.Lifecycle=%q", second.Existing, second.RunID, second.Lifecycle)
}

type probeSpy struct {
	parentCancel context.CancelFunc
	emit         func(runtimepkg.Request)
}

func (s *probeSpy) StartRun(_ context.Context, req runtimepkg.Request) (runtimepkg.Result, error) {
	if s.emit != nil {
		s.emit(req)
	}
	return runtimepkg.Result{Status: "failed"}, context.Canceled
}

// Probe 2: cancellation with one pending coalesced progress omission -> which terminal?
func TestProbeCancelledRunWithPendingOmissionTerminalOutcome(t *testing.T) {
	repository, owner := newProbeRepo(t)
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	var captured runtimepkg.Request
	spy := &probeSpy{}
	controlled := controlledRuntime{base: spy, repository: repository, owner: owner}
	spy.emit = func(req runtimepkg.Request) {
		captured = req
		event := runtimepkg.Event{ID: "e1", RunID: "r1", SessionID: "s1", Type: "tool", Kind: "tool", Payload: map[string]any{"tool": "bash", "state": "running"}}
		req.OnEvent(event)
		cancel()
		event2 := event
		event2.ID = "e2"
		req.OnEvent(event2)
	}
	result, runErr := controlled.StartRun(ctx, runtimepkg.Request{
		PromptRef: runtimepkg.PromptReference{OwnerKind: "sprint", Purpose: "execute"},
		Metadata:  map[string]string{"project": "p", "sprint": "1"},
	})
	t.Logf("PROBE2 result=%+v runErr=%v isCanceled=%v", result, runErr, errors.Is(runErr, context.Canceled))
	runID := runcontrol.RunID(captured.Metadata["run_control_run_id"])
	snapshot, err := repository.Snapshot(context.Background(), runID)
	if err != nil {
		t.Fatalf("snapshot: %v", err)
	}
	outcome := "<nil>"
	if snapshot.Terminal != nil {
		outcome = string(snapshot.Terminal.Outcome)
	}
	t.Logf("PROBE2 terminal outcome=%q lifecycle=%q reason=%q", outcome, snapshot.Lifecycle, snapshot.TerminalReason)
}
